"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[20266],{3331:(e,r,n)=>{n.d(r,{R:()=>a,x:()=>o});var t=n(36672);const i={},s=t.createContext(i);function a(e){const r=t.useContext(s);return t.useMemo((function(){return"function"==typeof e?e(r):{...r,...e}}),[r,e])}function o(e){let r;return r=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:a(e.components),t.createElement(s.Provider,{value:r},e.children)}},50625:(e,r,n)=>{n.r(r),n.d(r,{assets:()=>l,contentTitle:()=>o,default:()=>g,frontMatter:()=>a,metadata:()=>t,toc:()=>d});const t=JSON.parse('{"id":"2023/04/08","title":"2023-04-08","description":"Bygge GitHub med Ruby on Rails","source":"@site/i18n/nb/docusaurus-plugin-content-docs/current/2023/04/08.md","sourceDirName":"2023/04","slug":"/2023/04/08","permalink":"/nb/2023/04/08","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/nb/docusaurus-plugin-content-docs//current/2023/04/08.md","tags":[],"version":"current","frontMatter":{"localized_date":"8. april 2023","top_news":"Bygge GitHub med Ruby on Rails"},"sidebar":"defaultSidebar","previous":{"title":"2023-04-09","permalink":"/nb/2023/04/09"},"next":{"title":"2023-04-07","permalink":"/nb/2023/04/07"}}');var i=n(23420),s=n(3331);const a={localized_date:"8. april 2023",top_news:"Bygge GitHub med Ruby on Rails"},o="2023-04-08",l={},d=[{value:"Bygge GitHub med Ruby on Rails",id:"bygge-github-med-ruby-on-rails",level:2},{value:"Sp\xf8r Wirecutter: Kan du anbefale en ikke-smart TV for meg?",id:"sp\xf8r-wirecutter-kan-du-anbefale-en-ikke-smart-tv-for-meg",level:2},{value:"Codeberg - Raskt \xe5pen kildekode-alternativ til GitHub",id:"codeberg---raskt-\xe5pen-kildekode-alternativ-til-github",level:2},{value:"Fler\xe5rig ris: Plante \xe9n gang, h\xf8ste igjen og igjen",id:"fler\xe5rig-ris-plante-\xe9n-gang-h\xf8ste-igjen-og-igjen",level:2},{value:"60 millioner amerikanere har skatter som er s\xe5 enkle at skattemyndighetene kan gj\xf8re dem automatisk.",id:"60-millioner-amerikanere-har-skatter-som-er-s\xe5-enkle-at-skattemyndighetene-kan-gj\xf8re-dem-automatisk",level:2},{value:"Vi m\xe5 fortelle folk at ChatGPT vil lyve for dem, ikke diskutere lingvistikk.",id:"vi-m\xe5-fortelle-folk-at-chatgpt-vil-lyve-for-dem-ikke-diskutere-lingvistikk",level:2},{value:"Twitter tillater ikke retweeting av tweets som lenker til Substack.",id:"twitter-tillater-ikke-retweeting-av-tweets-som-lenker-til-substack",level:2},{value:"Western Digital skytjenester nede i 4 dager",id:"western-digital-skytjenester-nede-i-4-dager",level:2},{value:"Hvordan fungerer deling av databaser?",id:"hvordan-fungerer-deling-av-databaser",level:2},{value:"Hubble ser mulig l\xf8psk svart hull som skaper et spor av stjerner",id:"hubble-ser-mulig-l\xf8psk-svart-hull-som-skaper-et-spor-av-stjerner",level:2},{value:"New Zealands st\xf8rste datainnbrudd viser at datalagring er en sovende gigant innen datasikkerhet.",id:"new-zealands-st\xf8rste-datainnbrudd-viser-at-datalagring-er-en-sovende-gigant-innen-datasikkerhet",level:2},{value:"USA og Kina f\xf8rer krig under b\xf8lgene om internettkabler.",id:"usa-og-kina-f\xf8rer-krig-under-b\xf8lgene-om-internettkabler",level:2},{value:"Database &quot;sharding&quot; kom fra Ultima Online?",id:"database-sharding-kom-fra-ultima-online",level:2},{value:"Hvorfor delte Phreesia mine medisinske data etter at jeg meldte meg ut?",id:"hvorfor-delte-phreesia-mine-medisinske-data-etter-at-jeg-meldte-meg-ut",level:2},{value:"JavaScript-algoritmer: Algoritmer og datastrukturer implementert i JavaScript",id:"javascript-algoritmer-algoritmer-og-datastrukturer-implementert-i-javascript",level:2},{value:"SpaceX n\xe6rmer seg den f\xf8rste oppskytingen av Starship Super Heavy.",id:"spacex-n\xe6rmer-seg-den-f\xf8rste-oppskytingen-av-starship-super-heavy",level:2},{value:"Vis \xc5 bygge musikalske synthesizere med SQL-sp\xf8rsm\xe5l",id:"vis-\xe5-bygge-musikalske-synthesizere-med-sql-sp\xf8rsm\xe5l",level:2},{value:"Den lengste rette linjen i Storbritannia uten \xe5 krysse en offentlig vei.",id:"den-lengste-rette-linjen-i-storbritannia-uten-\xe5-krysse-en-offentlig-vei",level:2},{value:"Flipper Zero utestengt av Amazon for \xe5 v\xe6re en &quot;kortskimming-enhet&quot;.",id:"flipper-zero-utestengt-av-amazon-for-\xe5-v\xe6re-en-kortskimming-enhet",level:2},{value:"Reverse Engineering av Facebook Messenger API",id:"reverse-engineering-av-facebook-messenger-api",level:2},{value:"Maskinene til Tatjana van Vark.",id:"maskinene-til-tatjana-van-vark",level:2},{value:"Big Ball of Mud (1999)",id:"big-ball-of-mud-1999",level:2},{value:"Yann LeCun og Andrew Ng: Hvorfor den 6-m\xe5neders AI-pausen er en d\xe5rlig id\xe9 [video]",id:"yann-lecun-og-andrew-ng-hvorfor-den-6-m\xe5neders-ai-pausen-er-en-d\xe5rlig-id\xe9-video",level:2},{value:"NSA opprettet nettbasert cybersikkerhetskurs med hundrevis av klasser",id:"nsa-opprettet-nettbasert-cybersikkerhetskurs-med-hundrevis-av-klasser",level:2},{value:"Erstatning av d\xe5rlige systemer med d\xe5rlige systemer.",id:"erstatning-av-d\xe5rlige-systemer-med-d\xe5rlige-systemer",level:2},{value:"Neovim 0.9",id:"neovim-09",level:2},{value:"Sp\xf8r Hva er din beste ressurs for \xe5 holde deg oppdatert p\xe5 AI-utviklingen?",id:"sp\xf8r-hva-er-din-beste-ressurs-for-\xe5-holde-deg-oppdatert-p\xe5-ai-utviklingen",level:2},{value:"Direkte bevis p\xe5 bruk av flere stoffer i bronsealderen fra test av menneskeh\xe5r.",id:"direkte-bevis-p\xe5-bruk-av-flere-stoffer-i-bronsealderen-fra-test-av-menneskeh\xe5r",level:2},{value:"NYPD-offiserer skryter av \xe5 melke overtid i utilsiktet opptak",id:"nypd-offiserer-skryter-av-\xe5-melke-overtid-i-utilsiktet-opptak",level:2},{value:"Vis ChatGDB - GPT-drevet GDB-assistent",id:"vis-chatgdb---gpt-drevet-gdb-assistent",level:2}];function k(e){const r={a:"a",code:"code",h1:"h1",h2:"h2",header:"header",p:"p",...(0,s.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(r.header,{children:(0,i.jsx)(r.h1,{id:"2023-04-08",children:"2023-04-08"})}),"\n",(0,i.jsx)(r.h2,{id:"bygge-github-med-ruby-on-rails",children:"Bygge GitHub med Ruby on Rails"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://github.blog/2023-04-06-building-github-with-ruby-and-rails/",children:"Original"}),".\nGitHub.com er skrevet med Ruby on Rails og vedlikeholdes av over tusen ingeni\xf8rer med nesten 2 millioner kodelinjer. Selskapet oppgraderer til den nyeste Rails commit ukentlig med pull-foresp\xf8rsler og revisjonsgjennomganger. Fordelene med disse oppgraderingene inkluderer bedre h\xe5ndtering av databasetilkoblinger og raskere visningsgjengivelse, forbedret sikkerhet og lavere risiko for ukjente problemer. Testing av de nyeste versjonene identifiserer og l\xf8ser problemer f\xf8r utgivelse. Innlegget er en personvernerkl\xe6ring fra GitHub, som inneholder informasjon om produktfunksjoner, sikkerhet, historier, priser, ressurser, utvikler-API, partnere, plattform og st\xf8tte. Innlegget ser ikke ut til \xe5 ha noen ny informasjon eller hendelser, og det er uklart hvorfor det f\xe5r oppmerksomhet."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35478884",children:"Discussion Service"}),".\nGitHub bygget om plattformen sin med Ruby on Rails, noe som vekket interesse for dens potensielle innvirkning p\xe5 Rails-\xf8kosystemet og kravene til testdekning. Brukere fremhever utfordringer med \xe5 mestre Ruby, for eksempel ekstrem testdekning og potensial for fremtidige kodefeil. Noen brukere foresl\xe5r \xe5 bruke Sorbet for sterkere kontrolltyper. GitHubs bruk av Crystal-spr\xe5k og Rubys metaprogrammeringspotensial blir rost, mens noen kritiserer Rubys datavitenskapelige rom. Microsofts nylige oppgradering av Githubs Rails-plattform fra versjon 2.3 til 3 b\xf8d p\xe5 utfordringer, men statisk typing hjelper oppgraderinger. Utviklere reflekterer over avveiningene mellom teknologiske trender og etablert stabilitet, og noen bemerker at Rails er brukervennlig, men at visningslaget henger etter. Rammeverksoppgraderinger gj\xf8res mest effektivt gradvis, med god testing p\xe5 plass. Mange organisasjoner ser p\xe5 oppdatering av IT-infrastruktur som viktig, GitHubs testfunksjoner f\xe5r skryt, og Sorbet brukes av GitHub for Ruby og Rails."]}),"\n",(0,i.jsx)(r.h2,{id:"sp\xf8r-wirecutter-kan-du-anbefale-en-ikke-smart-tv-for-meg",children:"Sp\xf8r Wirecutter: Kan du anbefale en ikke-smart TV for meg?"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://www.nytimes.com/wirecutter/blog/ask-wirecutter-dumb-tvs/",children:"Original"}),".\nWirecutter foresl\xe5r \xe5 sikre smarte TV-er i stedet for \xe5 finne ikke-smarte alternativer p\xe5 grunn av personvernhensyn. Frakoblede TV-er kan mangle nyttige funksjoner. Eksperter anbefaler \xe5 velge bort datainnsamling, bare koble til Wi-Fi for fastvareoppdateringer og av og til str\xf8mming for \xe5 velge bort. Gamle TV-er, 4K-skjermer eller projektorer er alternativer. Lignende personvernproblemer vedvarer med andre Internett-tilkoblede enheter."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35484594",children:"Discussion Service"}),".\nEn artikkel diskuterer vanskeligheten med \xe5 finne en ikke-smart TV uten p\xe5trengende og un\xf8dvendige funksjoner. Foresl\xe5tte l\xf8sninger inkluderer bruk av en frakoblet smart-TV eller fysisk frakobling av moduler for \xe5 forhindre u\xf8nskede tilkoblinger. Det er bekymringer knyttet til personvern og datautfiltrering. Diskusjon rundt energibruk, potensielle automatiske tilkoblinger og treg oppstartsprosess for smart-TV-er fra brukernes side. Forslag til et potensielt navn p\xe5 en ikke-smart-TV og ideelle smart-TV-funksjoner. Bekymringer om datasporing og vanskeligheten med \xe5 starte et h\xf8ykvalitets, stumt skjermprojekt. Brukere diskuterer spesifikke skjermfunksjoner og vanskeligheten med \xe5 holde smart-TV-er frakoblet. TCLs uetiske oppf\xf8rsel og bekymringer for brukernes personvern fremheves."]}),"\n",(0,i.jsx)(r.h2,{id:"codeberg---raskt-\xe5pen-kildekode-alternativ-til-github",children:"Codeberg - Raskt \xe5pen kildekode-alternativ til GitHub"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://codeberg.org/",children:"Original"}),".\nCodeberg.org er en gratis programvareplattform med \xe5pen kildekode og Git-hosting som drives av brukerne via en ideell organisasjon i Berlin. Plattformen fremmer ogs\xe5 et fellesskap av likesinnede skapere av fri programvare og innhold uten sporing eller salg av brukerdata. Brukere kan registrere seg og v\xe6re vert for prosjektene sine p\xe5 nettstedet, og Codeberg e.V. opprettholder fellesskapet gjennom donasjoner og frivillige bidrag. Nettstedet er tilgjengelig p\xe5 flere spr\xe5k, og brukerne kan bidra til \xe5 forbedre tjenestene bak Codeberg."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35480056",children:"Discussion Service"}),".\nCodeberg er et raskt, \xe5pen kildekode-alternativ til Github som fokuserer p\xe5 samarbeid om fri programvare med \xe5pen kildekode. Discussion Service-brukere diskuterer om Codebergs fokus p\xe5 \xe5pen kildekode-etikk er for restriktivt, mens andre roser det for sitt engasjement. I diskusjonen om IT-infrastrukturens politiske natur hevder noen at n\xf8ytralitet er umulig, men likevel b\xf8r etterstrebes, mens andre hevder at politiske meninger er mer akseptable i IT enn i andre sammenhenger. Discussion Service-brukere diskuterer ogs\xe5 kodedelingsfilosofi, restriktiv lisensiering og bedriftsvennlige koders innvirkning p\xe5 FOSS-suksessraten. Codebergs ideelle status og forpliktelse til frie programvarelisenser roses. Plattformens raske hastighet og enkle grensesnitt blir verdsatt, men det er bekymringer knyttet til personvernet. Noen anbefaler Radicle som et alternativ til sentraliserte tjenester som Github."]}),"\n",(0,i.jsx)(r.h2,{id:"fler\xe5rig-ris-plante-\xe9n-gang-h\xf8ste-igjen-og-igjen",children:"Fler\xe5rig ris: Plante \xe9n gang, h\xf8ste igjen og igjen"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://www.npr.org/2023/03/23/1165680024/perennial-rice-plant-once-harvest-again-and-again",children:"Original"}),".\nForskere har skapt fler\xe5rige risstammer som holder seg produktive og vokser igjen etter hver h\xf8sting, noe som gir store milj\xf8fordeler, lavere karbonavtrykk, sunnere jord og b\xf8nder som ikke trenger \xe5 s\xe5 p\xe5 nytt. Disse stammene, som er avlet fram i l\xf8pet av de siste to ti\xe5rene, har blitt testet og h\xf8stet i fire \xe5r p\xe5 rad av 45 000 sm\xe5b\xf8nder. Eksperter sp\xe5r at hvis flere b\xf8nder tar i bruk de nye sortene, kan fordelene v\xe6re store for menneskene som dyrker dem, milj\xf8et og verdens befolkning som er avhengig av ris som basismat."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35481409",children:"Discussion Service"}),".\nFler\xe5rig ris kan redusere metanutslippene fra rismarker. Husdyrproduksjon har en betydelig milj\xf8p\xe5virkning. Klimaendringene vil f\xf8re til matmangel og andre problemer. Metan fra rismarker har ikke en betydelig innvirkning sammenlignet med andre kilder. Fler\xe5rig ris har potensielle fordeler, men ogs\xe5 utfordringer. Eksperter diskuterer landbruk og matproduksjon. Suksessen med irrigert fler\xe5rig ris skisseres. Fler\xe5rige avlinger kan spare arbeidskraft og innsatsfaktorer. Fler\xe5rige planter har fordeler for utvinning av jord og n\xe6ringsstoffer."]}),"\n",(0,i.jsx)(r.h2,{id:"60-millioner-amerikanere-har-skatter-som-er-s\xe5-enkle-at-skattemyndighetene-kan-gj\xf8re-dem-automatisk",children:"60 millioner amerikanere har skatter som er s\xe5 enkle at skattemyndighetene kan gj\xf8re dem automatisk."}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://www.vox.com/23055489/irs-automatic-filing-prepopulated-returns",children:"Original"}),'.\nMinst 41 % av amerikanske husholdninger, eller 62 millioner selvangivelsesenheter, kan f\xe5 hele selvangivelsen h\xe5ndtert av skattemyndighetene gjennom "forh\xe5ndsutfylte selvangivelser" uten ytterligere inngripen. Den mindre konservative tiln\xe6rmingen setter tallet til 73 millioner selvangivelser, eller 48 %. Potensialet for automatiske selvangivelser kan spare tid og bekymringer hvert \xe5r, og gj\xf8re skattesesongen mer effektiv. Artikkelen tar ogs\xe5 kort opp andre temaer som ikke er relatert til skatt, for eksempel den katolske kirkens overgrepskrise mot barn og Teslas kameraer som er under gransking. Den fremhever imidlertid f\xf8rst og fremst unike l\xf8sninger p\xe5 viktige problemer, som omtales i nyhetsbrevet Future Perfect. Artikkelen er n\xf8ytral og informativ, uten politisk eller religi\xf8s forutinntatthet.']}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35476709",children:"Discussion Service"}),".\n60 millioner amerikaneres skatter er enkle nok til at skattemyndighetene kan beregne dem automatisk. Den enkleste m\xe5ten for IRS \xe5 tjene penger p\xe5 er \xe5 revidere \xf8konomisk s\xe5rbare. Intuisjon bidrar til fenomenet med ugjennomsiktige lover. IRS-h\xe5ndhevelse er begrenset, s\xe5 amerikanere med lav inntekt blir revidert mer. Nylige skatteendringer betyr mindre rom for spesifiserte fradrag. IRS kan ikke maksimere sin automatiske skatteevne. IRS-budsjettet redusert, nylig \xf8kt; noen mener den ekstra finansieringen vil gj\xf8re det mulig for IRS \xe5 maksimere inntektene i stedet for \xe5 m\xe5lrette mot bestemte personer. Forslag om \xe5 skattlegge basert p\xe5 X-sats, fil hvis uenig. Forh\xe5ndsutfylte selvangivelser vil spare tid og penger, men er ikke idiotsikre. Bedriftslobbying bidrar til det n\xe5v\xe6rende selvbetjente skattesystemets kompleksitet. Det er ikke mulig \xe5 automatisere momsfradrag for kontanttransaksjoner. Skatteforberedelser sl\xf8ser bort milliarder av dollar og tid."]}),"\n",(0,i.jsx)(r.h2,{id:"vi-m\xe5-fortelle-folk-at-chatgpt-vil-lyve-for-dem-ikke-diskutere-lingvistikk",children:"Vi m\xe5 fortelle folk at ChatGPT vil lyve for dem, ikke diskutere lingvistikk."}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://simonwillison.net/2023/Apr/7/chatgpt-lies/",children:"Original"}),".\nArtikkelen diskuterer problemene rundt store spr\xe5kmodeller (LLM-er) som ChatGPT, som kan lyve for folk og ha feil som motst\xe5r fiksing. Forfatteren hevder at det er viktigere \xe5 advare folk om risikoen ved \xe5 bruke LLM-er enn \xe5 debattere lingvistikk. Selv om LLM-er kan v\xe6re nyttige, er de ikke sansende og kan ikke stoles p\xe5 n\xe5r det gjelder \xe5 gi saklig informasjon. Artikkelen reiser etiske sp\xf8rsm\xe5l om hvorvidt vi b\xf8r oppfordre folk til \xe5 bruke LLM-er til tross for deres mangler. Forfatteren konkluderer med at det er viktig \xe5 n\xe6rme seg LLM-er med forsiktighet og understreker behovet for \xe5 advare folk om at ChatGPT kan lyve."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35483823",children:"Discussion Service"}),".\nChatGPT kan villede brukere og m\xe5 gjentatte ganger f\xe5 beskjed om ikke \xe5 stole p\xe5 det. Dens nytte kan v\xe6re begrenset hvis tendensen til \xe5 hallusinere ikke er l\xf8st. ChatGPT mangler resonneringsevner og kan generere falsk informasjon. Noen er begeistret for dens potensielle fremskritt, men noen kritiserer den for dens manglende evne til \xe5 abstrahere eller resonnere. AI-generert tekst trenger skepsis og b\xf8r sees p\xe5 som en assistent som er godt belest, men potensielt utsatt for konfabulering. ChatGPT er imidlertid nyttig for \xe5 generere kodeeksempler og svare p\xe5 komplekse sp\xf8rsm\xe5l. Den gir n\xf8yaktige svar i opptil 99 % av tilfellene. Brukerne m\xe5 forst\xe5 begrensningene for \xe5 unng\xe5 \xe5 tillegge ChatGPT mer moral enn n\xf8dvendig."]}),"\n",(0,i.jsx)(r.h2,{id:"twitter-tillater-ikke-retweeting-av-tweets-som-lenker-til-substack",children:"Twitter tillater ikke retweeting av tweets som lenker til Substack."}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://arstechnica.com/tech-policy/2023/04/the-dumb-reason-twitter-wont-allow-retweeting-tweets-linking-to-substack/",children:"Original"}),".\nTwitter har begynt \xe5 begrense tweets som inneholder lenker til Substack.com som svar p\xe5 Substacks kunngj\xf8ring av et nytt produkt, Notes, som vil konkurrere direkte med Twitter. Brukere har lagt merke til at de ikke kan retweete eller svare p\xe5 tweets med Substack-lenker, og Twitter har tilsynelatende begynt \xe5 blokkere innbygging av tweets i Substack-innlegg. Denne begrensningen antas \xe5 v\xe6re Twitters fors\xf8k p\xe5 \xe5 dempe rekkevidden til en rival p\xe5 plattformen. Twitter begynte p\xe5 samme m\xe5te \xe5 blokkere lenker til konkurrerende sosiale medieplattformer i desember 2022. Substack har enn\xe5 ikke svart p\xe5 sp\xf8rsm\xe5l om denne saken."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35482222",children:"Discussion Service"}),".\nTwitter forb\xf8d retweets av tweets som lenket til Substack, og ved \xe5 like slike innlegg ble diskusjonen undertrykt. Tiltaket har utl\xf8st kritikk om ytringsfrihet, Elon Musks holdning til det og Substacks konkurranse. Mastodon ser ut til \xe5 erstatte Twitter for noen. Diskusjoner om PR, avhengighet av sosiale medier og tvilsom praksis dekkes. Ingen ny teknologi eller utgivelse nevnes."]}),"\n",(0,i.jsx)(r.h2,{id:"western-digital-skytjenester-nede-i-4-dager",children:"Western Digital skytjenester nede i 4 dager"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://status.mycloud.com/os4",children:"Original"}),".\nWestern Digital opplevde et str\xf8mbrudd som startet 2. april, som p\xe5virket tjenester inkludert My Cloud, My Cloud Home, SanDisk ibi og andre relaterte produkter, med en oppdatering lagt ut 3. april. Avbruddet fortsatte til 7. april, og p\xe5virket tilgangen til filer og applikasjoner. Lokal tilgang er tilgjengelig, slik at brukerne kan f\xe5 tilgang til sine personlige filer fra en Windows- eller MacOS-datamaskin. Andre tidligere hendelser inkluderer periodiske tilgangsproblemer, periodiske tilbakestillinger av passord og periodiske tilkoblingsproblemer med skytjenester. Enkelte brukere i Kina kan ogs\xe5 oppleve tilgangsproblemer."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35478007",children:"Discussion Service"}),".\nWestern Digitals skytjenester har v\xe6rt nede i fire dager, med kommentarer som diskuterer str\xf8mbruddet og selskapets garanti. Noen brukere diskuterer begrensningene ved GPTs spr\xe5kmodell og verdensmodell, og det stilles sp\xf8rsm\xe5l ved forst\xe5elsen av komplekse begreper. Kommentarene tar ogs\xe5 for seg juridiske forhold rundt GPTs tjenesteansvar og garantier. Brukerne diskuterer verdien av statussider under driftsavbrudd, og noen foresl\xe5r alternative metoder som chat. Brukerne diskuterer fordeler og ulemper med selvhosting, med en \xf8nsket fremtid der folks medier er tilgjengelige fra hvor som helst. Western Digitals tidligere problemer med SMR-stasjoner som ikke er merket p\xe5 riktig m\xe5te, har f\xe5tt noen brukere til \xe5 etterlyse en tilbakevending til lokale l\xf8sninger."]}),"\n",(0,i.jsx)(r.h2,{id:"hvordan-fungerer-deling-av-databaser",children:"Hvordan fungerer deling av databaser?"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://planetscale.com/blog/how-does-database-sharding-work",children:"Original"}),'.\nArtikkelen g\xe5r i dybden p\xe5 database sharding, og forklarer fordelene med \xe5 skalere ut i stedet for \xe5 skalere opp med forskjellige sharding-ordninger og algoritmer som diskuteres. Den dekker viktige aspekter som organisering av infrastruktur, oppretting av rutelag og migrasjonsplanlegging, og understreker betydningen av vedlikehold. Det gis en kort oversikt over rammeverk og verkt\xf8y for sharding som Vitess og Citus, med CockroachDB som innleder \xe6raen med "serverl\xf8se" databaser. PlanetScale, en ny akt\xf8r p\xe5 markedet, tilbyr en shard-native database bygget p\xe5 MySQL og Vitess sammen med sine tekniske ressurser.']}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35476518",children:"Discussion Service"}),".\nDebatter om fordeler og utfordringer med database sharding; velg system som samsvarer med data; gjennomstr\xf8mning av hurtigtaster er et problem ved automatisk sharding; Spanner/Cockroach eller Dynamo/Cassandra alternativer; CockroachDB tilbyr sterk konsistens og 2PC mellom shards; distribusjonskompleksitet krever betalte tjenester; fokus p\xe5 horisontal skalerbarhet for \xe5 unng\xe5 \xe5 investere i en enkelt maskin; god n\xf8kkeldesign kan forhindre hotspots; sharding av kunden er vanlig; sharding av flere leietakere foresl\xe5tt for skalerbarhet; Yugabyte, Cockroach og TiDB nevnt; hashing av alle data for synkronisering ikke skalerbar; svindlere utnytter Amazons praksis for samlokalisering av tabeller; MongoDB krever bedriftsst\xf8ttekontrakt."]}),"\n",(0,i.jsx)(r.h2,{id:"hubble-ser-mulig-l\xf8psk-svart-hull-som-skaper-et-spor-av-stjerner",children:"Hubble ser mulig l\xf8psk svart hull som skaper et spor av stjerner"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://hubblesite.org/contents/news-releases/2023/news-2023-010",children:"Original"}),".\nUnable to generate a summary as the text is a error message indicating that the request could not be satisfied due to a configuration error or too much traffic. Hvis du kontakter eieren av appen eller nettstedet eller g\xe5r gjennom CloudFront-dokumentasjonen, kan du feils\xf8ke og forhindre at denne feilen oppst\xe5r."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35476359",children:"Discussion Service"}),'.\nHubble-teleskopet s\xe5 et svart hull som etterlot seg et spor av stjerner, noe som f\xf8rte til spekulasjoner om dets effekt p\xe5 liv og nye steder \xe5 finne beboelige planeter. Hubble fant ogs\xe5 en sjelden galakse av Hoag-typen, omtrent dobbelt s\xe5 stor som Melkeveien. Forskere oppdaget et svart hull som skaper stjerner av gass, noe som kan p\xe5virke universet og tiltrekke seg avanserte sivilisasjoner. Et objekt som reiser veldig raskt gjennom rommet skaper en supersonisk p\xe5virkning p\xe5 gass, men bruken av "supersonisk" er sannsynligvis metaforisk. Discussion Service-brukere diskuterer scifi-historier som The Three-Body Problem, som gjenspeiler ulike meninger og anbefalinger for andre b\xf8ker i sjangeren. Brukerne diskuterer ogs\xe5 sjeldenheten av jordlignende liv og det antropomorfe prinsippet.']}),"\n",(0,i.jsx)(r.h2,{id:"new-zealands-st\xf8rste-datainnbrudd-viser-at-datalagring-er-en-sovende-gigant-innen-datasikkerhet",children:"New Zealands st\xf8rste datainnbrudd viser at datalagring er en sovende gigant innen datasikkerhet."}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://www.privacy.org.nz/publications/statements-media-releases/new-zealands-biggest-data-breach-shows-retention-is-the-sleeping-giant-of-data-security/",children:"Original"}),".\nOver en million newzealandske f\xf8rerkort og pass ble eksponert i Latitude Financial-datainnbruddet; noen poster var opptil 18 \xe5r gamle. New Zealands visekommiss\xe6r for personvern siterer datalagring som et kritisk problem i cybersikkerhetsangrep, og sier at bedrifter og organisasjoner m\xe5 begrense innsamling og lagring av data de ikke trenger. Byr\xe5er b\xf8r etablere en tidsplan for oppbevaring av personopplysninger, og enkeltpersoner b\xf8r utfordre organisasjoner de gir opplysninger til om hvorfor og hvordan de oppbevares. Personvern m\xe5 bli et viktig forretningssp\xf8rsm\xe5l, med tilsvarende beskyttelse som helse og sikkerhet. Latitude Financial kontakter alle ber\xf8rte kunder for \xe5 varsle om bruddet og hjelpe til med l\xf8sningen, samtidig som de samarbeider med tilsynsmyndigheter for \xe5 n\xf8ste opp i bruddet."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35478240",children:"Discussion Service"}),".\nNew Zealands st\xf8rste datainnbrudd understreker behovet for riktige retningslinjer for datalagring; sletting b\xf8r prioriteres. GDPR har gjort fremskritt, men datalagring er fortsatt utbredt. Discussion Service-brukere diskuterer ansvarlig datainnsamling, myndighetenes tilgang og datasikkerhet. Metoder for sletting av data og begrunnelser for oppbevaring diskuteres. Personopplysninger m\xe5 minimeres og behandles som giftige eiendeler. Bedrifter trenger bedre oppl\xe6ring i personvern."]}),"\n",(0,i.jsx)(r.h2,{id:"usa-og-kina-f\xf8rer-krig-under-b\xf8lgene-om-internettkabler",children:"USA og Kina f\xf8rer krig under b\xf8lgene om internettkabler."}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://www.reuters.com/investigates/special-report/us-china-tech-cables/",children:"Original"}),".\nUSA og Kina krangler om undersj\xf8iske kabler som overf\xf8rer alt fra e-post til milit\xe6re hemmeligheter. Den amerikanske regjeringen har grepet inn i minst seks private undersj\xf8iske kabelavtaler de siste fire \xe5rene for \xe5 isolere Kinas h\xf8yteknologiske sektor og begrense kinesisk tilgang til amerikansk teknologi. Det hvite hus tildelte nylig kabelkontrakten mellom Singapore og Frankrike til det USA-baserte selskapet SubCom, i stedet for Kinas HMN Tech, av sikkerhetsgrunner. Den amerikanske regjeringens aggressive innsats for \xe5 hindre kinesisk spionasje gjennom undersj\xf8iske kabler forstyrrer teknologigigantenes planer og skaper uro i bransjen. Kina tar igjen ved \xe5 forsinke et Meta-st\xf8ttet kabelprosjekt, Southeast Asia-Japan 2-kabelen."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35481712",children:"Discussion Service"}),'.\nUSA og Kina konkurrerer om undersj\xf8iske internettkabler, med bekymringer om nasjonale grenser og sensur. Forsinkelser og omlegginger av kabler har kostet teknologigigantene millioner. Eksperter anbefaler b\xf8ker om internasjonal infrastruktur. USA er bekymret for kinesisk spionasje og deres evne til \xe5 samle inn og filtrere internettrafikk. Kinas engasjement i den alliansefrie bevegelsen og Belt and Road Initiative reiser sp\xf8rsm\xe5l. Mange "cybersikkerhetsselskaper" mangler dyktige ingeni\xf8rer. CIAs torturprogram og ansvar for krigsforbrytelser diskuteres.']}),"\n",(0,i.jsx)(r.h2,{id:"database-sharding-kom-fra-ultima-online",children:'Database "sharding" kom fra Ultima Online?'}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://www.raphkoster.com/2009/01/08/database-sharding-came-from-uo/",children:"Original"}),".\nBeklager, jeg kan ikke generere et sammendrag basert p\xe5 denne teksten da det er en feilmelding og ikke relatert til det oppgitte emnet."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35479553",children:"Discussion Service"}),'.\nDiscussion Service-brukere diskuterer hvordan "sharding" i databaser ble inspirert av Ultima Online. Personlige historier forteller hvordan UO f\xf8rte til at de l\xe6rte \xe5 kode. Plakater mimrer om UOs spillkarakteristikker og dens innvirkning p\xe5 programmering.']}),"\n",(0,i.jsx)(r.h2,{id:"hvorfor-delte-phreesia-mine-medisinske-data-etter-at-jeg-meldte-meg-ut",children:"Hvorfor delte Phreesia mine medisinske data etter at jeg meldte meg ut?"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://www.statnews.com/2023/04/07/medical-data-privacy-phreesia/",children:"Original"}),".\nEn rapport belyser medisinske selskaper som deler pasientdata uten samtykke. Pasienten nektet datadeling, men fant likevel ut at hennes data ble delt av Phreesia. Forslag om en regel mot \xe5 presse pasienter til \xe5 gi samtykke. Behov for en standard reservasjonsmulighet for \xe5 gj\xf8re det klart og enkelt \xe5 reservere seg. Dagens prosess er tungvint. Ekspert foresl\xe5r \xe5 skille annonseteknologi fra helsetjenester. Forfatteren er etnografisk sosiolog og dataforsker."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35484978",children:"Discussion Service"}),".\nPhreesia delte medisinske data om pasienter som hadde reservert seg. Mange uttrykker bekymring for personvern og ansvarlighet, og mener at reklame som bruker sensitive medisinske data, ikke b\xf8r v\xe6re lovlig. Riktig dokumentasjon og rapportering m\xe5 gj\xf8res for \xe5 holde slike selskaper ansvarlige for brudd p\xe5 personvernet. Helsepersonells bruk av elektronisk innsjekking og m\xf8rke m\xf8nstre har blitt kritisert. Strenge lover om samtykke og h\xe5ndheving av datainnsamling er n\xf8dvendig i USA. Helseforetakenes profittmotiv og motvilje mot personvernregler for pasientopplysninger er ogs\xe5 et problem."]}),"\n",(0,i.jsx)(r.h2,{id:"javascript-algoritmer-algoritmer-og-datastrukturer-implementert-i-javascript",children:"JavaScript-algoritmer: Algoritmer og datastrukturer implementert i JavaScript"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://github.com/trekhleb/javascript-algorithms",children:"Original"}),".\nJavaScript-Algorithms er en omfattende samling av popul\xe6re algoritmer og datastrukturer implementert i JavaScript, organisert etter emne og paradigme. Det er egnet for l\xe6rings- og forskningsform\xe5l og produksjonsbruk. Brukere kan finne eksempler p\xe5 flere popul\xe6re algoritmer og datastrukturer, inkludert kryptering, evolusjon\xe6re algoritmer og maskinl\xe6ringsalgoritmer. Databasen inneholder forklaringer, Big O-notasjon og lenker til videre lesing. Det inneholder ogs\xe5 en lekeplass der leserne kan eksperimentere med koden. Avanserte algoritmer som branch and bound og dynamisk programmering er inkludert. Lesere b\xf8r merke seg at donasjoner er velkomne, og Node versjon 16 eller nyere er p\xe5krevd."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35479378",children:"Discussion Service"}),".\n\"Hacker News kommenterer det popul\xe6re GitHub-depotet 'JavaScript-algoritmer'. Brukere diskuterer spr\xe5kets egnethet for undervisning og praktisk bruk, noen advarer om uventet oppf\xf8rsel. Noen Discussion Service-brukere kritiserer implementeringen av 'addBefore()' og 'addAfter()'-metodene for koblede lister, mens andre er uenige. Discussion Service-brukere anbefaler ytterligere ressurser, kritiserer datastrukturens effektivitet og fremhever ressursverdien for l\xe6ringsalgoritmer.\""]}),"\n",(0,i.jsx)(r.h2,{id:"spacex-n\xe6rmer-seg-den-f\xf8rste-oppskytingen-av-starship-super-heavy",children:"SpaceX n\xe6rmer seg den f\xf8rste oppskytingen av Starship Super Heavy."}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://spacenews.com/spacex-closing-in-on-first-starship-super-heavy-launch/",children:"Original"}),".\nSpaceX planlegger f\xf8rste lansering av fullskala Starship-kj\xf8ret\xf8y senere i april, i p\xe5vente av myndighetsgodkjenning; Federal Aviation Administration har et hakk for en lanseringsdato 17. april, med reservedatoer 18. til 21. april, i sitt Operations Plan Advisory-dokument; Starship har blitt fullt stablet p\xe5 puten p\xe5 Starbase-anlegget i Boca Chica, Texas, og selskapet planlegger en lanserings\xf8velse neste uke etterfulgt av den f\xf8rste integrerte flytesten omtrent en uke senere; Det er uklart om Starship vil komme inn i bane, og deretter umiddelbart utf\xf8re en deorbit-brenning for \xe5 plaske ned, eller om det er en lang suborbital flytur."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35481775",children:"Discussion Service"}),".\nSpaceX n\xe6rmer seg oppskyting av Starship Super Heavy, med kommentarer som understreker dens betydning for kommersiell, milit\xe6r romfart og et skifte i tankesett. Offentlige kontrakter utgj\xf8r minst 80 % av SpaceX' inntekter. Starships kryogene raketter med flytende drivstoff kan brukes til avskrekkende oppdrag. Finansiering av oppskytinger er ikke bare avhengig av NASA. Video som sammenligner rakettst\xf8rrelser f\xe5r oppmerksomhet. SpaceX satser forel\xf8pig p\xe5 oppskyting 4/20. FAA vurderer sikkerhetshensyn. Blandede reaksjoner p\xe5 Musks respektl\xf8se holdning."]}),"\n",(0,i.jsx)(r.h2,{id:"vis-\xe5-bygge-musikalske-synthesizere-med-sql-sp\xf8rsm\xe5l",children:"Vis \xc5 bygge musikalske synthesizere med SQL-sp\xf8rsm\xe5l"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://github.com/ClickHouse/NoiSQL",children:"Original"}),".\nEt GitHub-depot kalt NoiSQL muliggj\xf8r musikalsk lydgenerering med SQL-sp\xf8rringer ved hjelp av grunnleggende b\xf8lger, oscillatorer, sequencere, LFO-er og st\xf8ygeneratorer. Opprettet i et 44,1 kHz 16-biters stereo PCM-format, kan brukerne kontrollere signaler ved \xe5 definere funksjoner og uttrykk i SQL. NoiSQL gir instruksjoner og eksempler for \xe5 l\xe6re hvordan du bruker det. Prosjektet kan generere musikalske noter og rytmer med ClickHouse og kan lage forskjellige filformater. Selv om prosjektet har noen begrensninger, er det en innovativ m\xe5te \xe5 eksperimentere med ClickHouse-funksjonene p\xe5, og det kan potensielt utvides til \xe5 omfatte videogenerering. Brukerne kan bidra med nye eksempler til prosjektet."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35482636",children:"Discussion Service"}),".\nEt prosjekt som bygger synthesizere med SQL-sp\xf8rringer. Discussion Service-kommentatorer setter pris p\xe5 den unike ideen og nevner lignende prosjekter. Noen brukere bemerker mangelen p\xe5 forklaring og potensielle s\xe5rbarheter for SQL-injeksjon."]}),"\n",(0,i.jsx)(r.h2,{id:"den-lengste-rette-linjen-i-storbritannia-uten-\xe5-krysse-en-offentlig-vei",children:"Den lengste rette linjen i Storbritannia uten \xe5 krysse en offentlig vei."}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://www.statsmapsnpix.com/2023/04/the-longest-straight-line-in-great.html",children:"Original"}),".\nDet er funnet en lengre rett linje i Storbritannia uten \xe5 krysse en offentlig vei enn den som ble identifisert av Ordnance Survey i 2019. Den lengste rette linjen mellom veier i Storbritannia er ogs\xe5 den lengste i hele Storbritannia. OS Open Roads-produktet gir mange flotte \xe5pne data, men noen ganger inkluderer det veier som ikke er offentlige. Begrensede lokale adkomstveier er vanligvis ikke-asfalterte private veier. Den lengste strekningen i Storbritannia ligger vest for A9 i stedet for \xf8st. Selv om kartdata er nyttige, b\xf8r de tas med en klype salt."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35481380",children:"Discussion Service"}),".\nDen lengste rette linjen i Storbritannia som er oppdaget; kanskje ikke helt rett. Noe diskusjon om avstand fra veier, tilgjengelighet til grusveier og befolkning. Brukere nevner avsidesliggende omr\xe5der rundt om i verden og muligheten for \xe5 automatisere s\xf8ket. En diskusjon om Schengen-avtalen og passstatistikk."]}),"\n",(0,i.jsx)(r.h2,{id:"flipper-zero-utestengt-av-amazon-for-\xe5-v\xe6re-en-kortskimming-enhet",children:'Flipper Zero utestengt av Amazon for \xe5 v\xe6re en "kortskimming-enhet".'}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://www.bleepingcomputer.com/news/technology/flipper-zero-banned-by-amazon-for-being-a-card-skimming-device-/",children:"Original"}),'.\nAmazon har forbudt salg av Flipper Zero p\xe5 sin plattform, og beskylder den for \xe5 v\xe6re en "kortskimming-enhet". Enheten er et kompakt, b\xe6rbart og programmerbart verkt\xf8y som kan bidra til \xe5 eksperimentere med og feils\xf8ke forskjellige digitale og maskinvareenheter. Brukere har vist frem dens evner og stimulert Amazons forbud. Noen lenker til tidligere tilgjengelige Amazon-sider som selger Flipper Zero-verkt\xf8yet er d\xf8de, mens andre viser det som "utilgjengelig". Det brasilianske nasjonale telekommunikasjonsbyr\xe5et har ogs\xe5 beslaglagt innkommende Flipper Zero-kj\xf8p basert p\xe5 p\xe5st\xe5tt bruk av kriminelle. Du kan fortsatt kj\xf8pe Flipper Zero fra produsentens offisielle butikk.']}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35481580",children:"Discussion Service"}),".\nAmazon forbyr kj\xf8p av Flipper Zero da det regnes som en kortskimming-enhet, men enheten kan kj\xf8pes fra den offisielle butikken. Kj\xf8pere synes det er interessant, men ikke nyttig. Retningslinjene for lockpick-forbud er inkonsekvente og udokumenterte. Produsenter av Flipper Zero bruker et USA-basert selskap for betalinger, noe som gir sikkerhetsproblemer. Det stilles sp\xf8rsm\xe5l ved Amazons motivasjon for \xe5 unng\xe5 overskrifter som forbinder dem med kriminalitet. Flipper Zero er forbudt p\xe5 grunn av potensialet for ulovlige aktiviteter, men noen hevder at det er i strid med Amazons retningslinjer. Noen ser potensial for at Amazon kan utvikle sin egen piratkopi. Flipper Zero er fjernet fra Amazon og eBay, men kan fortsatt kj\xf8pes via det offisielle nettstedet."]}),"\n",(0,i.jsx)(r.h2,{id:"reverse-engineering-av-facebook-messenger-api",children:"Reverse Engineering av Facebook Messenger API"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://intuitiveexplanations.com/tech/messenger",children:"Original"}),".\nForfatteren reverse-engineered Facebook Messenger API for \xe5 lage Messyger, et kommandolinjeprogram. Innlegget forklarer p\xe5loggingsprosessen og informasjonskapsler og tilbyr Python-kode p\xe5 GitHub. Det legges vekt p\xe5 etisk oppf\xf8rsel, og det gis tips for \xe5 gj\xf8re foresp\xf8rsler utenfor nettleseren."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35477160",children:"Discussion Service"}),".\nUtviklere hevder oppbl\xe5st og ineffektiv Messenger API. Facebooks appbibliotek har JNI-bindinger. Behov for tredjepartsklienter, Digital Markets Act nevnt. Bekymring for s\xf8ppelpost og datainnsamling, deling av verkt\xf8y for reverse engineering. Profittmotiver driver s\xf8ppelpostreduksjon, noen st\xf8tter inngripen fra myndighetene. Regulering b\xf8r fokusere p\xe5 skyleverand\xf8rer, ikke inngjerdede hager. Brukere stiller sp\xf8rsm\xe5l ved begrepet eiendom og redning av selskaper."]}),"\n",(0,i.jsx)(r.h2,{id:"maskinene-til-tatjana-van-vark",children:"Maskinene til Tatjana van Vark."}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://craftsmanshipmuseum.com/artisan/tatjana-van-vark/",children:"Original"}),".\nTatjana van Vark, en uavhengig forsker fra Nederland, har bygget, kopiert og restaurert en lang rekke vitenskapelige instrumenter. Hennes forseggjorte prosjekter viser fremragende h\xe5ndverk og oppmerksomhet p\xe5 detaljer, ofte med kompleksitet som g\xe5r utover overflaten. Tatjanas arbeid har f\xf8rt henne inn i mange omr\xe5der av vitenskapelige studier, og hun har bygget deler innen elektronikk, optikk, kryptologi, organisk kjemi og mer. Til tross for at hun er selvl\xe6rt maskinist, inneholder verkstedet hennes maskiner av h\xf8y kvalitet som kan h\xe5ndtere kravene til presisjonsarbeidet hennes. Arbeidet hennes er vitenskapelig h\xe5ndverk p\xe5 h\xf8yeste niv\xe5, med imponerende fotoutstillinger tilgjengelig p\xe5 nettstedet hennes."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35483539",children:"Discussion Service"}),".\nTatjana van Varks arbeid er utrolig, og hun er en ekstrem hacker som konstruerer instrumenter helt fra bunnen av. Hun har et bredt spekter av ferdigheter og har produsert mange verk som det vil ta et helt liv \xe5 gjennomg\xe5. Det er grunn til bekymring over at det blir stadig f\xe6rre eksperter fordi teknologien utvikler seg raskere enn vi klarer \xe5 l\xe6re den opp. Tatjana van Vark og h\xe5ndverkere som henne har aldri v\xe6rt vanlige."]}),"\n",(0,i.jsx)(r.h2,{id:"big-ball-of-mud-1999",children:"Big Ball of Mud (1999)"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://www.laputan.org/mud/",children:"Original"}),".\nArtikkelen utforsker BIG BALL OF MUD-programvarearkitekturen og hvorfor den vedvarer til tross for h\xf8ytenkende tiln\xe6rminger. Syv m\xf8nstre blir diskutert, inkludert engangskode og stykkevis vekst, og \xe5rsakene bak dem, for eksempel tidsbegrensninger og fors\xf8mmelse av arkitektur. For tidlig arkitektur kan hindre utvikling, og uerfarenhet eller utskifting av ansatte kan begrense raffinement. Parprogrammering og kodegjennomganger anbefales for umiddelbar granskning, mens refaktorering, reparasjon og konsolidering er avgj\xf8rende for \xe5 bekjempe BIG BALL OF MUD. Det understreker viktigheten av inkrementell vekst, vedlikehold, tilpasning og streng testing. Det kan v\xe6re n\xf8dvendig \xe5 gjenoppbygge et system, men refaktorering kan v\xe6re et alternativ ved \xe5 hente arkitektoniske elementer fra det n\xe5v\xe6rende systemet."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35481309",children:"Discussion Service"}),'.\nArtikkelen "Big Ball of Mud (1999)" er en anerkjent artikkel om programvareutvikling. Flere brukere roser dens innsikt og relevans, og siterer den som en omfattende forklaring p\xe5 det man ser i virkelige situasjoner hver uke. Andre peker p\xe5 andre lignende viktige artikler eller senere utviklinger innen programvareteknikk, for eksempel mikrotjenester. Noen brukere kommenterer sine personlige erfaringer knyttet til artikkelen. Til slutt kritiserer noen brukere artikkelens formatering eller bemerker at den har v\xe6rt lagt ut tidligere.']}),"\n",(0,i.jsx)(r.h2,{id:"yann-lecun-og-andrew-ng-hvorfor-den-6-m\xe5neders-ai-pausen-er-en-d\xe5rlig-id\xe9-video",children:"Yann LeCun og Andrew Ng: Hvorfor den 6-m\xe5neders AI-pausen er en d\xe5rlig id\xe9 [video]"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://www.youtube.com/watch?v=BY9KV8uCtj4",children:"Original"}),".\nDette er ikke det faktiske innholdet i artikkelen. Vennligst oppgi teksten slik at jeg kan oppsummere."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35484093",children:"Discussion Service"}),".\nYann LeCun og Andrew Ng kritiserer den 6 m\xe5neder lange AI-pausen, og antyder at den er urealistisk og gir en fordel for OpenAI. Debatter om AI-vinter, menneskelig tankerepresentasjon og samfunnsforstyrrelser fremheves. AI-fremgang gir uventede evner utover tekst og uttrykker bekymring for tap av arbeidsplasser og fattigdom. Ekspertene har delte meninger om effektiviteten av pausen i KI-utviklingen og risikoen ved uregulert KI. Den potensielle trusselen om at kunstig intelligens skal overg\xe5 menneskelig intelligens og overv\xe5kingsteknologier for dyp l\xe6ring blir tatt opp, sammen med bekymringer om tilpasning av kunstig intelligens til menneskelige m\xe5l."]}),"\n",(0,i.jsx)(r.h2,{id:"nsa-opprettet-nettbasert-cybersikkerhetskurs-med-hundrevis-av-klasser",children:"NSA opprettet nettbasert cybersikkerhetskurs med hundrevis av klasser"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://clark.center/c/nccp",children:"Original"}),".\nNSA har opprettet et nettbasert cybersikkerhetskurs med hundrevis av klasser tilgjengelig. Kurset, kalt CLARK, dekker et bredt spekter av emner, inkludert nettverkssikkerhet, kryptografi og cybertrusler. Kursene er utviklet for b\xe5de nybegynnere og eksperter, og er gratis tilgjengelig for alle som har tilgang til internett. Det har v\xe6rt en viss kontrovers rundt kurset, og noen kritikere hevder at det gir NSA en bakd\xf8r for \xe5 f\xe5 tilgang til privat informasjon. NSA har imidlertid avvist disse p\xe5standene og sier at kurset er rent pedagogisk."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35481456",children:"Discussion Service"}),".\nNSA har opprettet et kurs i cybersikkerhet, men det er bekymringer rundt byr\xe5ets bruk av 0day-utnyttelser i offensive operasjoner. Noen brukere bemerker at skillet mellom angrep og forsvar er mindre illevarslende enn det ser ut til. Kurset er en del av CLARK-systemet, som er delvis finansiert av NSA, men drives hovedsakelig av Towson University. Noen brukere kritiserer mangelen p\xe5 dekning av visse emner i kurset."]}),"\n",(0,i.jsx)(r.h2,{id:"erstatning-av-d\xe5rlige-systemer-med-d\xe5rlige-systemer",children:"Erstatning av d\xe5rlige systemer med d\xe5rlige systemer."}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://seths.blog/2023/04/replacing-bad-systems-with-bad-systems/",children:"Original"}),".\nI blogginnlegget sitt bruker Seth metaforen om utdaterte parkometre for \xe5 illustrere behovet for \xe5 revurdere og forbedre d\xe5rlige systemer. Selv om det kan virke dyrt \xe5 erstatte dem, har sentraliserte systemer som Parkmobile-appen ofte sine egne mangler. For \xe5 g\xe5 tilbake til det opprinnelige m\xe5let om \xe5 generere inntekter og forhindre heldagsparkering, foresl\xe5r Seth \xe5 implementere en gratis app som skanner en kode for \xe5 tillate en periode med parkeringstid. Andre inntektsbringende alternativer inkluderer en nettbasert betalingstjeneste eller salg av parkeringskort med ulike rabattalternativer. Selv om det er vanskelig \xe5 ta UX-valg for et offentlig system, har distribuerte systemer som WordPress blomstret p\xe5 grunn av deres desentraliserte og brukervennlige design. Den viktigste fordelen med distribuerte systemer er deres evne til \xe5 forbedre seg over tid, i stedet for \xe5 forkalke som sentraliserte systemer. For \xe5 komme videre foresl\xe5r Seth at vi prioriterer bedre l\xf8sninger i stedet for flere l\xf8sninger."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35476350",children:"Discussion Service"}),".\nEt enklere parkeringssystem i Danmark har manuelle urskiver, med b\xf8ter for juksemakere. Brukere peker p\xe5 lignende systemer i utlandet. Komplekse l\xf8sninger brukes ofte til tross for enkle alternativer. Parkeringsautomatene i Chicago genererte 200 millioner dollar p\xe5 10 \xe5r. Nye elektroniske parkeringsautomater er mindre praktiske enn de klassiske. Myndighetene sliter med betalingssystemene, og overlater det noen ganger til leverand\xf8rene. Parkeringsautomater brukes hovedsakelig til penger, men de forhindrer ogs\xe5 heldagsparkering. Artikkelen hadde ikke noe poeng if\xf8lge en kommentator, mens en annen kritiserer forfatteren."]}),"\n",(0,i.jsx)(r.h2,{id:"neovim-09",children:"Neovim 0.9"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://github.com/neovim/neovim/commit/040f1459849ab05b04f6bb1e77b3def16b4c2f2b",children:"Original"}),".\nNeovim versjon 0.9.0 er utgitt, med endringer i iconv, libintl, valgfrie parametere, lua2dox, semantiske tokens, '+tui', st\xf8tte for Yarn node-moduler og utheving av kodeblokker. Vim versjon 8.2.2902 har ogs\xe5 blitt utgitt med feilrettinger og forbedret Lua-skripting og LSP-st\xf8tte. Neovims siste utgivelse presenterer spennende nye funksjoner og stabilitetsforbedringer, mens Vim fokuserer p\xe5 feilrettinger og forbedret funksjonalitet. Neovims oppdateringer inkluderer forbedringer av 'treesitter', 'tui' og 'windows', fra programvareoppdateringer til forbedret dokumentasjon, som str\xf8mlinjeformer Neovim-opplevelsen og styrker dens posisjon som dyktig og brukervennlig. Andre oppdateringer inkluderer endringer i 'expect_unchanged()'-funksjonen, EditorConfig og syntaksutheving for hjelpefiler, en hodel\xf8s instans, forbedrede LSP-klientfunksjoner og plugin-st\xf8tte for brukergrensesnitt."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35480629",children:"Discussion Service"}),".\nNeovim 0.9.0 undeprecates 'exrc' og legger til en \"tillitsdatabase\". Eksperter anbefaler appImage eller .local for installasjon. St\xf8tte for EditorConfig er n\xe5 innebygd. Debatt om Neovims fordeler, mens noen kritiserer fragmentering, foresl\xe5r andre plugin-administratorer. Neovim \xe5pner for nye verkt\xf8y og plugins. Lua har fordeler for plugin-utvikling. Helix Editor har objekt-verb-modell, null konfigurasjonsspr\xe5kserver og en veileder. Utvalget er mindre fleksibelt, men brukerne skryter av brukervennlighet og effektivitet."]}),"\n",(0,i.jsx)(r.h2,{id:"sp\xf8r-hva-er-din-beste-ressurs-for-\xe5-holde-deg-oppdatert-p\xe5-ai-utviklingen",children:"Sp\xf8r Hva er din beste ressurs for \xe5 holde deg oppdatert p\xe5 AI-utviklingen?"}),"\n",(0,i.jsx)(r.p,{children:"N/A (Siden dette bare er generelle instruksjoner for oppsummering, er det ingen tekst \xe5 oppsummere)."}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35479853",children:"Discussion Service"}),".\nDiscussion Service-brukere anbefaler ressurser for \xe5 holde seg oppdatert om AI-utviklingen, inkludert nettstedet Papers with Code, blogger og nyhetsbrev. Forsiktighet anbefales p\xe5 grunn av overbelastning av informasjon. Noen tilbyr ressurser for nybegynnere. Nylige fremskritt innen AI, inkludert maskinvare og algoritmiske innovasjoner, har forbedret oppl\xe6ringen av store nevrale nettverk og oppn\xe5dd ytelse p\xe5 menneskelig niv\xe5. Debatten om revolusjonerende gjennombrudd fortsetter."]}),"\n",(0,i.jsx)(r.h2,{id:"direkte-bevis-p\xe5-bruk-av-flere-stoffer-i-bronsealderen-fra-test-av-menneskeh\xe5r",children:"Direkte bevis p\xe5 bruk av flere stoffer i bronsealderen fra test av menneskeh\xe5r."}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://www.nature.com/articles/s41598-023-31064-2",children:"Original"}),".\nEn studie fant direkte bevis p\xe5 flere psykoaktive plantearter i bronsealderens Menorca ved hjelp av analyse av menneskeh\xe5r. H\xe5ret inneholdt efedrin, atropin og skopolamin. Arkeologer utleder vanligvis bruken av bevissthetsendrende stoffer fra gjenstander, men denne analysen er direkte. Denne oppdagelsen kaster nytt lys over narkotikabruk i eldgamle samfunn, og indikerer spesialisert kunnskap og potensiell sjamanistisk bruk. Studien viser hvor viktig det er \xe5 forst\xe5 tidligere kulturers rolle n\xe5r det gjelder psykoaktive planter og narkotikabruk. Flere studier viser bevis p\xe5 bruk av psykoaktive planter i eldgamle kulturer, noe som understreker den lange historien til menneskelig narkotikabruk."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35486923",children:"Discussion Service"}),".\nH\xe5rpr\xf8ver avsl\xf8rer narkotika i bronsealderen med flere psykoaktive arter. Kommentarer diskuterer samfunnsmessige konsekvenser av narkotikabruk, personlige valg, utdanning og verdier. Narkotikaforbud forankret i folkehelse, moral og rasisme. N\xf8ytral artikkel unng\xe5r politisk partiskhet og spekulasjoner."]}),"\n",(0,i.jsx)(r.h2,{id:"nypd-offiserer-skryter-av-\xe5-melke-overtid-i-utilsiktet-opptak",children:"NYPD-offiserer skryter av \xe5 melke overtid i utilsiktet opptak"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://gothamist.com/news/nypd-officers-brag-about-milking-overtime-call-detainees-names-in-accidental-recording",children:"Original"}),'.\nEt utilsiktet opptak gjort under arrestasjonen av en bygningsarbeider har avsl\xf8rt politibetjenter som skryter av \xe5 "melke overtid" og bruker nedsettende spr\xe5k overfor arrestanter. Opptaket kaster lys over hvordan nylige strafferettsreformer har p\xe5virket m\xe5ten politifolk behandler arrestasjoner og krever inn overtid p\xe5. Det antydes at politibetjenter utnytter endringer i kausjons- og oppdagelseslover for \xe5 akkumulere ekstra overtid. NYPD har nektet \xe5 kommentere opptaket, som ogs\xe5 inneholder uf\xf8lsomme kommentarer fra betjenter om arrestanter.']}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35487036",children:"Discussion Service"}),".\nNYPD-offiserer skryter av \xe5 melke overtid, men artikkelen avsl\xf8rer deres bruk av skjellsord, vitser om institusjonalisering av mennesker osv. Noen mener at rettsh\xe5ndhevelse i USA har mye verre problemer, og at politiets overtid er en avledningsman\xf8ver. Andre sier at \xe5 melke overtid ved \xe5 forlenge forvaring er grunnlovsstridig og fortjener anklager om forbrytelser. Korrupsjonen i politiet har f\xf8rt til krav om at det m\xe5 avskaffes og erstattes. Mangel p\xe5 skikkelig tilsyn og kontroll gj\xf8r det mulig \xe5 melke overtid og beg\xe5 lovbrudd. Det er bekymring for oppf\xf8rselen til personer som f\xe5r v\xe5pen og s\xe6rbehandling i henhold til loven."]}),"\n",(0,i.jsx)(r.h2,{id:"vis-chatgdb---gpt-drevet-gdb-assistent",children:"Vis ChatGDB - GPT-drevet GDB-assistent"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://github.com/pgosar/ChatGDB",children:"Original"}),".\nChatGDB er et verkt\xf8y som forbedrer feils\xf8kingsopplevelsen i GDB ved \xe5 bruke kraften til ChatGPT, slik at naturlige spr\xe5kkommandoer kan utf\xf8res automatisk. Brukere kan ogs\xe5 be ChatGPT om \xe5 forklare kommandoen som nettopp ble kj\xf8rt eller til og med stille den et sp\xf8rsm\xe5l. For \xe5 installere m\xe5 Python versjon 3.3 eller nyere og pip installeres, etterfulgt av kommandoen ",(0,i.jsx)(r.code,{children:"pip3 install chatgdb"})," og opprette en kj\xf8rbar fil med ",(0,i.jsx)(r.code,{children:"chatgdb -k <API KEY>"}),". Verkt\xf8yet kan brukes i GDB ved \xe5 skrive ",(0,i.jsx)(r.code,{children:"chat"})," etterfulgt av \xf8nsket kommando, og kommandoen ",(0,i.jsx)(r.code,{children:"explain"})," kan brukes for \xe5 be om en forklaring av den forrige kommandoen eller for \xe5 stille et sp\xf8rsm\xe5l."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35483933",children:"Discussion Service"}),'.\nChatGDB er en GPT-drevet GDB-assistent som forbedrer feils\xf8kingsarbeidsflyten. Discussion Service-brukeren noterer programmets minimale kode. ChatGPT akselererer brukerens forst\xe5else for ukjent teknologi, refactoring oppgaver. CLI-versjon av ChatGPT foresl\xe5tt. ChatGPT fremskynder arbeidsflyter, til tross for at noen brukere foretrekker muskelminne. ChatGPT-3 presenterer naturlig spr\xe5kprompt for GDB, nyttig for "minnelekkasjer og segmenteringsfeil." Grensesnittet er fortsatt uh\xe5ndterlig i visse scenarier, mens skrift og fargevalg blir godt mottatt.']})]})}function g(e={}){const{wrapper:r}={...(0,s.R)(),...e.components};return r?(0,i.jsx)(r,{...e,children:(0,i.jsx)(k,{...e})}):k(e)}}}]);